220	// resolvePullablePlacements returns every cluster placement of one GitHub
221	// upstream the caller may pull (clone). It backs `repo clone /gh/<owner>/<repo>`
222	// and deliberately differs from listMirrorsForRepo: that reads the
223	// affiliation-scoped mirror list (repo#list), which omits public mirrors the
224	// caller holds no grant on, so the shorthand used to fail on a public repo that
225	// clones fine by full entire:// URL. This hits the pull-gated /mirrors/placements
226	// endpoint instead — the same authority the clone's STS exchange enforces — so
227	// anything clonable resolves, public or private-with-grant.
228	//
229	// owner/repo arrive already lowercased from parseMirrorCloneRef; the server
230	// matches case-insensitively regardless. An empty result means not mirrored or
231	// not pullable, and the caller surfaces that.
232	func resolvePullablePlacements(ctx context.Context, c *coreapi.Client, owner, repo string) ([]coreapi.ResolvedPlacement, error) {
233		out, err := c.ResolveMirrorPlacements(ctx, coreapi.ResolveMirrorPlacementsParams{
234			Provider: coreapi.ResolveMirrorPlacementsProviderGithub,
235			Owner:    owner,
236			Repo:     repo,
237		})
238		if err != nil {
239			return nil, fmt.Errorf("resolve mirror placements: %w", err)
240		}
241		return out.Placements, nil
242	}
